# ═══════════════════════════════════════════════════════
# 查询函数
# ═══════════════════════════════════════════════════════

def _find_index(sizes, value):
    """在尺寸段列表中查找索引"""
    for i, (low, high) in enumerate(sizes):
        if value == 0 and low == 0:
            if value <= high:
                return i
        elif low < value <= high:
            return i
    return -1


def get_straightness_flatness(size, grade):
    """查询直线度/平面度公差值
    Args: size(mm), grade(1-12)
    Returns: (公差值μm, 尺寸段标签) 或 None
    """
    if grade < 1 or grade > 12:
        return None
    idx = _find_index(STRAIGHTNESS_FLATNESS_SIZES, size)
    if idx == -1:
        return None
    return (STRAIGHTNESS_FLATNESS[grade-1][idx], STRAIGHTNESS_FLATNESS_LABELS[idx])


def get_roundness_cylindricity(size, grade):
    """查询圆度/圆柱度公差值
    Args: size(mm), grade(0-12)
    Returns: (公差值μm, 尺寸段标签) 或 None
    """
    if grade < 0 or grade > 12:
        return None
    idx = _find_index(ROUNDNESS_SIZES, size)
    if idx == -1:
        return None
    return (ROUNDNESS[grade][idx], ROUNDNESS_LABELS[idx])


def get_parallelism(size, grade):
    """查询平行度公差值"""
    if grade < 1 or grade > 12:
        return None
    idx = _find_index(POSITION_SIZES, size)
    if idx == -1:
        return None
    return (PARALLELISM[grade-1][idx], POSITION_LABELS[idx])


def get_perpendicularity(size, grade):
    """查询垂直度公差值"""
    if grade < 1 or grade > 12:
        return None
    idx = _find_index(POSITION_SIZES, size)
    if idx == -1:
        return None
    return (PERPENDICULARITY[grade-1][idx], POSITION_LABELS[idx])


def get_runout_symmetry(size, grade):
    """查询同轴度/对称度/圆跳动/全跳动公差值"""
    if grade < 1 or grade > 12:
        return None
    idx = _find_index(RUNOUT_SIZES, size)
    if idx == -1:
        return None
    return (RUNOUT[grade-1][idx], RUNOUT_LABELS[idx])


def recommend_by_machining(method):
    """根据加工方法推荐公差等级"""
    return MACHINING_RECOMMEND.get(method, None)


